def count_divisor_functions(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return 2 * len(divs)

for n in range(1, 11):
